1	/**
2	 * The shared `Repo` contract suite. Any implementation must pass it, so the
3	 * in-memory twin cannot drift from Firestore semantics. Call
4	 * {@link describeRepoContract} with a factory that returns a fresh, empty repo
5	 * (and an optional teardown) — ticket 02 runs it against the in-memory repo,
6	 * ticket 03 drops in the Firestore adapter in a disposable `test-*` namespace.
7	 *
8	 * This file imports Vitest, so it is test support, not product code: it is
9	 * excluded from the API build and never imported outside a `*.test.ts`.
10	 */
11	import { afterEach, beforeEach, describe, expect, it } from "vitest";
12	import {
13	  ActiveRunExistsError,
14	  emptyFunnel,
15	  jobKey,
16	  type Evaluation,
17	  type EvaluationChange,
18	  type Posting,
19	  type Repo,
20	  type Run,
21	  type UserDoc,
22	} from "@auto-apply/shared";
23	
24	export interface RepoHarness {
25	  repo: Repo;
26	  teardown?: () => Promise<void> | void;
27	}
28	
29	/** Lets every microtask (and the current macrotask) drain before we assert. */
30	function flush(): Promise<void> {
31	  return new Promise((resolve) => setTimeout(resolve, 0));
32	}
33	
34	function aUser(overrides: Partial<UserDoc> = {}): UserDoc {
35	  return { uid: "user-1", profile: {}, preferences: {}, settings: {}, ...overrides };
36	}
37	
38	function aRun(overrides: Partial<Run> = {}): Run {
39	  const now = new Date().toISOString();
40	  return {
41	    runId: "run-1",
42	    uid: "user-1",
43	    status: "discovering",
44	    funnel: emptyFunnel(),
45	    reason: null,
46	    createdAt: now,
47	    updatedAt: now,
48	    ...overrides,
49	  };
50	}
51	
52	function aPosting(jobId = "1"): Posting {
53	  return {
54	    ats: "greenhouse",
55	    board: "acme",
56	    jobId,
57	    title: "Staff Engineer",
58	    company: "Acme",
59	    location: "Remote",
60	    descriptionText: "Build things.",
61	    applyUrl: `https://boards.greenhouse.io/acme/jobs/${jobId}`,
62	  };
63	}
64	
65	function anEvaluation(posting: Posting, overrides: Partial<Evaluation> = {}): Evaluation {
66	  const now = new Date().toISOString();
67	  return {
68	    jobKey: jobKey(posting),
69	    runId: "run-1",
70	    posting,
71	    status: "queued",
72	    verdict: null,
73	    score: null,
74	    reason: null,
75	    createdAt: now,
76	    updatedAt: now,
77	    ...overrides,
78	  };
79	}
80	
81	export function describeRepoContract(
82	  name: string,
83	  createHarness: () => Promise<RepoHarness> | RepoHarness,
84	): void {
85	  describe(`Repo contract: ${name}`, () => {
86	    let repo: Repo;
87	    let teardown: (() => Promise<void> | void) | undefined;
88	
89	    beforeEach(async () => {
90	      const harness = await createHarness();
91	      repo = harness.repo;
92	      teardown = harness.teardown;
93	    });
94	
95	    afterEach(async () => {
96	      await teardown?.();
97	    });
98	
99	    describe("users", () => {
100	      it("returns null before a user is seeded, then the seeded document", async () => {
101	        expect(await repo.getUser("user-1")).toBeNull();
102	        await repo.seedUserIfMissing("user-1", aUser({ profile: { title: "Staff" } }));
103	        const user = await repo.getUser("user-1");
104	        expect(user?.uid).toBe("user-1");
105	        expect(user?.profile).toEqual({ title: "Staff" });
106	      });
107	
108	      it("leaves an existing user untouched on a second seed", async () => {
109	        await repo.seedUserIfMissing("user-1", aUser({ profile: { title: "Staff" } }));
110	        await repo.seedUserIfMissing("user-1", aUser({ profile: { title: "Overwritten" } }));
111	        const user = await repo.getUser("user-1");
112	        expect(user?.profile).toEqual({ title: "Staff" });
113	      });
114	    });
115	
116	    describe("active run (the future 409, D17)", () => {
117	      it("has no active run initially and reports one after createRun", async () => {
118	        expect(await repo.getActiveRun("user-1")).toBeNull();
119	        await repo.createRun(aRun());
120	        expect((await repo.getActiveRun("user-1"))?.runId).toBe("run-1");
121	      });
122	
123	      it("rejects a second concurrent run for the same user", async () => {
124	        await repo.createRun(aRun());
125	        await expect(repo.createRun(aRun({ runId: "run-2" }))).rejects.toBeInstanceOf(
126	          ActiveRunExistsError,
127	        );
128	      });
129	
